`timescale 1ns/1ps
// Default-off tile successor. Select one bank's exact bytes before conversion.
// Onehot selection is generated by the existing held bank decode, not a new protocol.
module ot_qwen_rom_raw_group #(
    parameter integer W=16, BANKS=5, MUT=0
)(input wire clk, input wire [BANKS*2*W*8-1:0] cap,
  input wire [BANKS-1:0] sel, output wire [2*W*16-1:0] q);
    localparam integer BW=2*W*8, SB=(BANKS+1)/2;
    wire [BW-1:0] south [0:BANKS], north [0:BANKS];
    assign south[0]=0; assign north[0]=0;
    genvar b,e;
    for(b=0;b<BANKS;b=b+1) begin:g_bank
        wire [BW-1:0] word = cap[b*BW+:BW] & {BW{sel[b]}};
        assign south[b+1]=(b<SB)?south[b]|word:south[b];
        assign north[b+1]=(b<SB)?north[b]:north[b]|word;
    end
    (* keep *) reg [BW-1:0] raw_s,raw_n;
    always @(posedge clk) begin raw_s<=south[BANKS];raw_n<=north[BANKS];end
    function automatic [15:0] bf(input [7:0] c);
        reg [7:0] mag,norm;reg [2:0] msb;integer k;
        begin
            mag=c[7]?(~c+8'd1):c;msb=0;
            for(k=0;k<8;k=k+1) if(mag[k]) msb=k[2:0];
            norm=mag<<(3'd7-msb);
            bf=(mag==0)?16'd0:{c[7],(8'd127+{5'd0,msb}),norm[6:0]};
        end
    endfunction
    wire [2*BW-1:0] cs,cn;
    for(e=0;e<BW/8;e=e+1) begin:g_conv
        assign cs[e*16+:16]=bf(raw_s[e*8+:8]);
        assign cn[e*16+:16]=bf(raw_n[e*8+:8]);
    end
    reg [2*BW-1:0] gs,gn,rs,rn;
    always @(posedge clk) begin
        gs<=cs;gn<=cn;rs<=(MUT!=0)?cs:gs;rn<=(MUT!=0)?cn:gn;
    end
    assign q=rs|rn;
endmodule
